arguments.argument:
// A modal text prompt laid out like the Source engine's VGUI dialogs, drawn in the menus' style.
// Open it with input_dialog_create, which fills in everything below.
dialogTitle = "";
dialogMessage = "";
inputText = "";
maxLength = 0;
onClose = "";
userData = 0;
accepted = false;
caretStart = current_time;

panelWidth = 330;
buttonWidth = 72;
buttonHeight = 24;

// Stop anything underneath from taking the typing meant for this dialog
with (MenuController)
    editing = -1;
